// USERS APIs

// Get all users
app.get('/api/users', async (c) => {
  try {
    // Get user info including role_id
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const roleId = userInfo.roleId
    const tenantId = userInfo.tenantId
    
    // Resolve role_name from u.role_id only (scalar subqueries). Avoid GROUP BY + permission JOINs —
    // SQLite can surface inconsistent non-aggregated columns; old rows then showed wrong role_name (e.g. "employee").
    let query = `
      SELECT u.*,
             (SELECT role_name FROM roles WHERE id = u.role_id) AS role_name,
             (SELECT description FROM roles WHERE id = u.role_id) AS role_description,
             t.company_name AS tenant_name,
             (SELECT COUNT(DISTINCT permission_id) FROM role_permissions WHERE role_id = u.role_id) AS permissions_count
      FROM users u
      LEFT JOIN tenants t ON u.tenant_id = t.id`
    
    // Superadmin (role_id = 1) can see all users
    // Other roles see only their tenant's users
    if (roleId !== 1 && tenantId) {
      query += ` WHERE u.tenant_id = ${tenantId}`
    }
    
    query += `
      ORDER BY u.id DESC`
    
    const { results } = await c.env.DB.prepare(query).all()
    const normalizedResults = (results || []).map((u: any) => ({
      ...u,
      role_name: getRoleDisplayName(u.role_id, u.role_name)
    }))
    return c.json({ success: true, data: normalizedResults })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// TEMP: HR backfill — remove endpoint + UI when migration complete
app.post('/api/admin/sync-users-to-hr', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const superU = isSuperAdminUser(userInfo)
    const companyAdmin = userInfo.roleId === 2
    if (!superU && !companyAdmin) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    let tenantFilter: number | null = null
    if (superU) {
      const body = (await c.req.json().catch(() => ({}))) as { tenant_id?: unknown }
      const raw = body?.tenant_id
      if (raw != null && String(raw).trim() !== '') {
        const p = parseInt(String(raw), 10)
        tenantFilter = Number.isNaN(p) ? null : p
      }
    } else if (userInfo.tenantId != null && !Number.isNaN(Number(userInfo.tenantId))) {
      tenantFilter = userInfo.tenantId
    } else {
      return c.json({ success: false, error: 'No tenant context' }, 400)
    }

    const { synced, skipped, errors } = await bulkSyncUsersToHrEmployees(c.env.DB, tenantFilter)
    return c.json({
      success: true,
      message: 'تمت المزامنة',
      synced,
      skipped,
      errors,
      tenant_id: tenantFilter,
    })
  } catch (error: any) {
    return c.json({ success: false, error: error.message || 'Sync failed' }, 500)
  }
})

