// Get workflow timeline for a specific request
app.get('/api/workflow/timeline/:requestId', async (c) => {
  try {
    const requestId = c.req.param('requestId')
    
    // Get all stage transitions
    const { results: transitions } = await c.env.DB.prepare(`
      SELECT 
        wst.*,
        from_stage.stage_name_ar as from_stage_name,
        from_stage.stage_color as from_stage_color,
        from_stage.stage_icon as from_stage_icon,
        to_stage.stage_name_ar as to_stage_name,
        to_stage.stage_color as to_stage_color,
        to_stage.stage_icon as to_stage_icon,
        u.full_name as transitioned_by_name
      FROM workflow_stage_transitions wst
      LEFT JOIN workflow_stages from_stage ON wst.from_stage_id = from_stage.id
      LEFT JOIN workflow_stages to_stage ON wst.to_stage_id = to_stage.id
      LEFT JOIN users u ON wst.transitioned_by = u.id
      WHERE wst.request_id = ?
      ORDER BY wst.created_at ASC
    `).bind(requestId).all()
    
    // Get all actions for this request
    const { results: actions } = await c.env.DB.prepare(`
      SELECT 
        wsa.*,
        ws.stage_name_ar,
        ws.stage_color,
        ws.stage_icon,
        u.full_name as performed_by_name
      FROM workflow_stage_actions wsa
      LEFT JOIN workflow_stages ws ON wsa.stage_id = ws.id
      LEFT JOIN users u ON wsa.performed_by = u.id
      WHERE wsa.request_id = ?
      ORDER BY wsa.created_at ASC
    `).bind(requestId).all()
    
    // Get all tasks for this request
    const { results: tasks } = await c.env.DB.prepare(`
      SELECT 
        wst.*,
        ws.stage_name_ar,
        assigned_user.full_name as assigned_to_name,
        completed_user.full_name as completed_by_name
      FROM workflow_stage_tasks wst
      LEFT JOIN workflow_stages ws ON wst.stage_id = ws.id
      LEFT JOIN users assigned_user ON wst.assigned_to = assigned_user.id
      LEFT JOIN users completed_user ON wst.completed_by = completed_user.id
      WHERE wst.request_id = ?
      ORDER BY wst.due_date ASC
    `).bind(requestId).all()
    
    return c.json({ 
      success: true, 
      data: {
        transitions,
        actions,
        tasks
      }
    })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

const WORKFLOW_STATUS_BY_STAGE: Record<string, 'pending' | 'under_review' | 'approved' | 'rejected' | 'cancelled'> = {
  draft: 'pending',
  submitted: 'pending',
  missing_docs: 'under_review',
  processing: 'under_review',
  underwriting: 'under_review',
  conditional_approval: 'under_review',
  documentation: 'under_review',
  approved: 'approved',
  final_approval: 'approved',
  disbursed: 'approved',
  active: 'approved',
  closed: 'approved',
  rejected: 'rejected',
  cancelled: 'cancelled'
}

function mapWorkflowStageToRequestStatus(stageName?: string | null) {
  if (!stageName) return null
  return WORKFLOW_STATUS_BY_STAGE[stageName] || null
}

// Update request stage
app.post('/api/workflow/update-stage', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    const { requestId, newStageId, notes, userId } = await c.req.json()

    const stage = await c.env.DB.prepare(`
      SELECT stage_name FROM workflow_stages WHERE id = ?
    `).bind(newStageId).first() as { stage_name?: string } | null

    const currentRequest = await c.env.DB.prepare(`
      SELECT status FROM financing_requests WHERE id = ?
    `).bind(requestId).first() as { status?: string } | null

    const mappedStatus = mapWorkflowStageToRequestStatus(stage?.stage_name || null)

    const updateFields = [
      'current_stage_id = ?',
      'stage_entered_at = CURRENT_TIMESTAMP'
    ]
    const updateParams: any[] = [newStageId]

    if (mappedStatus) {
      updateFields.push('status = ?')
      updateParams.push(mappedStatus)

      if (mappedStatus === 'pending') {
        updateFields.push("pending_at = COALESCE(pending_at, CURRENT_TIMESTAMP)")
      } else if (mappedStatus === 'under_review') {
        updateFields.push("under_review_at = COALESCE(under_review_at, CURRENT_TIMESTAMP)")
      } else if (mappedStatus === 'approved') {
        updateFields.push("approved_at = COALESCE(approved_at, CURRENT_TIMESTAMP)")
      } else if (mappedStatus === 'rejected') {
        updateFields.push("rejected_at = COALESCE(rejected_at, CURRENT_TIMESTAMP)")
      }

      if (mappedStatus === 'approved' || mappedStatus === 'rejected' || mappedStatus === 'under_review') {
        updateFields.push('reviewed_at = CURRENT_TIMESTAMP')
      }
    }

    updateParams.push(requestId)

    // Update stage + keep legacy status aligned for compatibility
    await c.env.DB.prepare(`
      UPDATE financing_requests 
      SET ${updateFields.join(', ')}
      WHERE id = ?
    `).bind(...updateParams).run()
    
    // The trigger will automatically create a transition record
    // But we can add notes if provided
    if (notes) {
      await c.env.DB.prepare(`
        UPDATE workflow_stage_transitions 
        SET notes = ?, transitioned_by = ?
        WHERE request_id = ? AND to_stage_id = ?
        ORDER BY created_at DESC
        LIMIT 1
      `).bind(notes, userId, requestId, newStageId).run()
    }

    if (mappedStatus && currentRequest?.status && currentRequest.status !== mappedStatus) {
      await c.env.DB.prepare(`
        INSERT INTO financing_request_status_history (request_id, old_status, new_status, changed_by, notes)
        VALUES (?, ?, ?, ?, ?)
      `).bind(requestId, currentRequest.status, mappedStatus, userId || null, notes || '').run()
    }
    
    return c.json({ success: true, message: 'تم تحديث مرحلة الطلب بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

