// ============= PAYMENTS APIs =============

// Get all payments (with tenant filtering)
app.get('/api/payments', async (c) => {
  try {
    const authHeader = c.req.header('Authorization')
    const token = authHeader?.replace('Bearer ', '')
    let tenant_id = null
    
    if (token) {
      try {
        // Decode token (format: userId:tenantId:timestamp:random)
        const decoded = atob(token)
        const [userId, tenantId] = decoded.split(':')
        tenant_id = tenantId === 'null' ? null : parseInt(tenantId)
      } catch (e) {
        // Token invalid or expired
      }
    }
    
    let query = `
      SELECT 
        p.*,
        c.full_name as customer_name,
        u.full_name as employee_name
      FROM payments p
      LEFT JOIN customers c ON p.customer_id = c.id
      LEFT JOIN users u ON p.employee_id = u.id
    `
    
    const bindings: any[] = []
    
    if (tenant_id) {
      query += ' WHERE p.tenant_id = ?'
      bindings.push(tenant_id)
    }
    
    query += ' ORDER BY p.created_at DESC'
    
    const { results } = await c.env.DB.prepare(query).bind(...bindings).all()
    
    return c.json({ success: true, data: results })
  } catch (error: any) {
    console.error('Payments API error:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Create new payment
app.post('/api/payments', async (c) => {
  try {
    const authHeader = c.req.header('Authorization')
    const token = authHeader?.replace('Bearer ', '')
    
    if (!token) {
      return c.json({ success: false, error: 'غير مصرح' }, 401)
    }
    
    // Decode token (format: userId:tenantId:timestamp:random)
    const decoded = atob(token)
    const [userId, tenantId] = decoded.split(':')
    const tenant_id = tenantId === 'null' ? null : parseInt(tenantId)
    const created_by = parseInt(userId)
    
    if (!tenant_id) {
      return c.json({ success: false, error: 'يجب أن تكون مرتبطاً بشركة' }, 403)
    }
    
    const data = await c.req.json()
    
    // Validate required fields
    if (!data.financing_request_id || !data.customer_id || !data.amount || !data.payment_date) {
      return c.json({ success: false, error: 'البيانات المطلوبة ناقصة' }, 400)
    }
    
    await c.env.DB.prepare(`
      INSERT INTO payments (
        financing_request_id, customer_id, tenant_id, employee_id,
        amount, payment_date, payment_method, receipt_number, notes, created_by
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      data.financing_request_id,
      data.customer_id,
      tenant_id,
      data.employee_id || null,
      data.amount,
      data.payment_date,
      data.payment_method || 'cash',
      data.receipt_number || null,
      data.notes || null,
      created_by
    ).run()
    
    return c.json({ success: true, message: 'تم حفظ سند القبض بنجاح' })
  } catch (error: any) {
    console.error('Error creating payment:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Delete payment
app.delete('/api/payments/:id', async (c) => {
  try {
    const authHeader = c.req.header('Authorization')
    const token = authHeader?.replace('Bearer ', '')
    
    if (!token) {
      return c.json({ success: false, error: 'غير مصرح' }, 401)
    }
    
    // Decode token (format: userId:tenantId:timestamp:random)
    const decoded = atob(token)
    const [userId, tenantId] = decoded.split(':')
    const tenant_id = tenantId === 'null' ? null : parseInt(tenantId)
    const id = c.req.param('id')
    
    // Verify payment belongs to this tenant
    if (tenant_id) {
      const payment = await c.env.DB.prepare(
        'SELECT tenant_id FROM payments WHERE id = ?'
      ).bind(id).first()
      
      if (payment && payment.tenant_id !== tenant_id) {
        return c.json({ success: false, error: 'غير مصرح بحذف هذا السند' }, 403)
      }
    }
    
    await c.env.DB.prepare('DELETE FROM payments WHERE id = ?').bind(id).run()
    
    return c.json({ success: true, message: 'تم حذف السند بنجاح' })
  } catch (error: any) {
    console.error('Error deleting payment:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// API for calculator (accepts JSON with new customer data)
// Multi-tenant calculator submit API
app.post('/api/c/:tenant/calculator/submit-request', async (c) => {
  try {
    const tenantSlug = c.req.param('tenant')
    const data = await c.req.json()
    
    // Get tenant_id from slug
    const tenant = await c.env.DB.prepare(`
      SELECT id FROM tenants WHERE slug = ? AND status = 'active'
    `).bind(tenantSlug).first()
    
    if (!tenant) {
      return c.json({ success: false, error: 'شركة غير موجودة' }, 404)
    }
    
    const tenant_id = tenant.id
    
    // Step 1: Check if customer exists (by national_id or phone) within same tenant
    let customer = await c.env.DB.prepare(`
      SELECT id FROM customers WHERE (national_id = ? OR phone = ?) AND tenant_id = ?
    `).bind(data.national_id || '', data.phone || '', tenant_id).first()
    
    let customer_id
    
    if (customer) {
      customer_id = customer.id
      
      // Update customer info
      await c.env.DB.prepare(`
        UPDATE customers 
        SET full_name = ?, phone = ?, email = ?, 
            birthdate = ?, monthly_salary = ?,
            employer_name = ?, job_title = ?,
            work_start_date = ?, city = ?,
            financing_amount = ?, monthly_obligations = ?, financing_type_id = ?,
            enrollment_source = COALESCE(enrollment_source, 'calculator')
        WHERE id = ?
      `).bind(
        data.full_name || '',
        data.phone || '',
        data.email || null,
        data.birthdate || null,
        data.monthly_salary || 0,
        data.employer || '',
        data.job_title || '',
        data.work_start_date || null,
        data.city || '',
        data.requested_amount || 0,
        data.monthly_obligations || 0,
        data.financing_type_id || null,
        customer_id
      ).run()
    } else {
      // Create new customer with tenant_id
      try {
        const customerResult = await c.env.DB.prepare(`
          INSERT INTO customers (
            full_name, phone, email, national_id, 
            birthdate, monthly_salary, employer_name, 
            job_title, work_start_date, city, tenant_id,
            financing_amount, monthly_obligations, financing_type_id,
            enrollment_source
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          data.full_name || '',
          data.phone || '',
          data.email || null,
          data.national_id || '',
          data.birthdate || null,
          data.monthly_salary || 0,
          data.employer || '',
          data.job_title || '',
          data.work_start_date || null,
          data.city || '',
          tenant_id,
          data.requested_amount || 0,
          data.monthly_obligations || 0,
          data.financing_type_id || null,
          'calculator'
        ).run()
        
        customer_id = customerResult.meta.last_row_id
      } catch (insertError: any) {
        if (insertError.message && insertError.message.includes('UNIQUE')) {
          // Try to find existing customer (might be in a different tenant)
          const existingCustomer = await c.env.DB.prepare(`
            SELECT id FROM customers WHERE (national_id = ? OR phone = ?)
          `).bind(data.national_id || '', data.phone || '').first()
          
          if (existingCustomer) {
            // Customer exists, update their info and use their ID
            customer_id = existingCustomer.id
            
            // Update customer with new tenant_id and info
            await c.env.DB.prepare(`
              UPDATE customers 
              SET full_name = ?, phone = ?, email = ?, 
                  birthdate = ?, monthly_salary = ?,
                  employer_name = ?, job_title = ?,
                  work_start_date = ?, city = ?, tenant_id = ?,
                  financing_amount = ?, monthly_obligations = ?, financing_type_id = ?
              WHERE id = ?
            `).bind(
              data.full_name || '',
              data.phone || '',
              data.email || null,
              data.birthdate || null,
              data.monthly_salary || 0,
              data.employer || '',
              data.job_title || '',
              data.work_start_date || null,
              data.city || '',
              tenant_id,
              data.requested_amount || 0,
              data.monthly_obligations || 0,
              data.financing_type_id || null,
              customer_id
            ).run()
          } else {
            throw insertError
          }
        } else {
          throw insertError
        }
      }
    }
    
    // Step 2: Create financing request with tenant_id
    const requestResult = await c.env.DB.prepare(`
      INSERT INTO financing_requests (
        customer_id, financing_type_id, selected_bank_id,
        requested_amount, salary_at_request, duration_months,
        monthly_obligations, monthly_payment,
        status, notes, tenant_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)
    `).bind(
      customer_id,
      data.financing_type_id || null,
      data.bank_id || data.selected_bank_id || null,
      data.requested_amount || 0,
      data.monthly_salary || 0,
      data.duration || data.duration_months || 0,
      data.monthly_obligations || 0,
      data.monthly_payment || 0,
      data.notes || null,
      tenant_id
    ).run()
    
    const requestId = requestResult.meta.last_row_id
    
    return c.json({ 
      success: true, 
      request_id: requestId,
      message: 'تم إرسال طلبك بنجاح'
    })
  } catch (error: any) {
    console.error('Calculator submit error:', error)
    console.error('Error details:', {
      message: error.message,
      stack: error.stack,
      data: error
    })
    return c.json({ 
      success: false, 
      error: 'حدث خطأ أثناء إرسال الطلب. الرجاء المحاولة مرة أخرى.',
      details: error.message 
    }, 500)
  }
})

// Save customer initial data from calculator (before completing request)
app.post('/api/calculator/save-customer', async (c) => {
  try {
    const data = await c.req.json()
    
    // Extract tenant_id from the request path or default to null
    const tenantSlug = data.tenant_slug || null
    let tenant_id = null
    
    if (tenantSlug) {
      const tenant = await c.env.DB.prepare(`
        SELECT id FROM tenants WHERE slug = ? AND status = 'active'
      `).bind(tenantSlug).first()
      
      if (tenant) {
        tenant_id = tenant.id
      }
    }
    
    // If no tenant_id from slug, try to get default tenant (first active tenant)
    // This ensures calculator customers are assigned to a company
    if (!tenant_id) {
      const defaultTenant = await c.env.DB.prepare(`
        SELECT id FROM tenants WHERE status = 'active' ORDER BY id LIMIT 1
      `).first()
      
      if (defaultTenant) {
        tenant_id = defaultTenant.id
      }
    }
    
    // Check if customer already exists
    let customer = await c.env.DB.prepare(`
      SELECT id FROM customers WHERE phone = ?
    `).bind(data.phone).first()
    
    let customer_id

    const solutionsEncoded =
      Array.isArray(data.solutions)
        ? JSON.stringify(
            data.solutions.map((x: { note?: string } | string) => ({
              note: String(typeof x === 'string' ? x : x?.note ?? '').trim()
            }))
          )
        : null
    
    if (customer) {
      // Update existing customer with calculator data
      customer_id = customer.id

      const saveCustUpdateBind = [
        data.name,
        data.birthdate,
        data.salary,
        data.amount,
        data.obligations || 0,
        data.financing_type_id,
        data.duration_months || null,
        data.best_bank_id || null,
        data.best_rate || null,
        data.monthly_payment || null,
        data.total_payment || null,
        tenant_id,
        solutionsEncoded,
        customer_id
      ] as const
      try {
        await c.env.DB.prepare(`
        UPDATE customers 
        SET full_name = ?, 
            birthdate = ?, 
            monthly_salary = ?,
            financing_amount = ?,
            monthly_obligations = ?,
            financing_type_id = ?,
            financing_duration_months = ?,
            best_bank_id = ?,
            best_rate = ?,
            monthly_payment = ?,
            total_payment = ?,
            calculation_date = CURRENT_TIMESTAMP,
            tenant_id = COALESCE(?, tenant_id),
            solutions_json = IFNULL(?, solutions_json),
            enrollment_source = COALESCE(enrollment_source, 'calculator')
        WHERE id = ?
      `).bind(...saveCustUpdateBind).run()
      } catch (e: unknown) {
        if (!isMissingCustomerSolutionsColumnError(e)) throw e
        await c.env.DB.prepare(`
        UPDATE customers 
        SET full_name = ?, 
            birthdate = ?, 
            monthly_salary = ?,
            financing_amount = ?,
            monthly_obligations = ?,
            financing_type_id = ?,
            financing_duration_months = ?,
            best_bank_id = ?,
            best_rate = ?,
            monthly_payment = ?,
            total_payment = ?,
            calculation_date = CURRENT_TIMESTAMP,
            tenant_id = COALESCE(?, tenant_id),
            enrollment_source = COALESCE(enrollment_source, 'calculator')
        WHERE id = ?
      `).bind(
          data.name,
          data.birthdate,
          data.salary,
          data.amount,
          data.obligations || 0,
          data.financing_type_id,
          data.duration_months || null,
          data.best_bank_id || null,
          data.best_rate || null,
          data.monthly_payment || null,
          data.total_payment || null,
          tenant_id,
          customer_id
        ).run()
      }
    } else {
      // Create new customer with initial calculator data
      // Generate temporary unique national_id to avoid UNIQUE constraint error
      const tempNationalId = `TEMP-${Date.now()}-${Math.random().toString(36).substring(7)}`

      const saveCustInsertBind = [
        data.name,
        data.phone,
        data.birthdate,
        data.salary,
        data.amount,
        data.obligations || 0,
        data.financing_type_id,
        data.duration_months || null,
        data.best_bank_id || null,
        data.best_rate || null,
        data.monthly_payment || null,
        data.total_payment || null,
        tempNationalId,
        tenant_id
      ] as const
      let result: { meta: { last_row_id: number } }
      try {
        result = await c.env.DB.prepare(`
        INSERT INTO customers (
          full_name, phone, birthdate, monthly_salary,
          financing_amount, monthly_obligations, financing_type_id,
          financing_duration_months, best_bank_id, best_rate,
          monthly_payment, total_payment, calculation_date,
          national_id, tenant_id, solutions_json,
          enrollment_source
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?, ?, ?, ?)
      `).bind(...saveCustInsertBind, solutionsEncoded ?? '[]', 'calculator').run() as { meta: { last_row_id: number } }
      } catch (e: unknown) {
        if (!isMissingCustomerSolutionsColumnError(e)) throw e
        result = await c.env.DB.prepare(`
        INSERT INTO customers (
          full_name, phone, birthdate, monthly_salary,
          financing_amount, monthly_obligations, financing_type_id,
          financing_duration_months, best_bank_id, best_rate,
          monthly_payment, total_payment, calculation_date,
          national_id, tenant_id,
          enrollment_source
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?, ?, ?)
      `).bind(...saveCustInsertBind, 'calculator').run() as { meta: { last_row_id: number } }
      }

      customer_id = result.meta.last_row_id
    }

    // Auto-assign calculator customers to a role-4 employee using the fair queue,
    // but only if they don't already have an assignment.
    if (tenant_id && customer_id) {
      const existingAssignment = await c.env.DB.prepare(
        `SELECT 1 as ok FROM customer_assignments WHERE customer_id = ? LIMIT 1`
      ).bind(customer_id).first<{ ok: number }>()

      if (!existingAssignment?.ok) {
        const { results: staffRows } = await c.env.DB.prepare(`
          SELECT id FROM users
          WHERE role_id = 4 AND tenant_id = ? AND is_active = 1
          ORDER BY id ASC
        `).bind(tenant_id).all<{ id: number }>()

        const staff = (staffRows || []) as { id: number }[]
        if (staff.length) {
          const stateRow = await c.env.DB.prepare(`
            SELECT last_auto_assigned_user_id
            FROM tenant_customer_auto_assign_state
            WHERE tenant_id = ?
            LIMIT 1
          `).bind(tenant_id).first<{ last_auto_assigned_user_id: number | null }>()

          const staffIds = staff.map((s) => s.id)
          const lastId: number | null = stateRow?.last_auto_assigned_user_id ?? null
          function pickNextUserId(last: number | null): number {
            if (last == null) return staffIds[0]
            const idx = staffIds.indexOf(last)
            if (idx === -1) return staffIds[0]
            return staffIds[(idx + 1) % staffIds.length]
          }

          const employeeId = pickNextUserId(lastId)
          const assignedBy = 1
          const noteAr = 'تعيين تلقائي (الحاسبة)'

          const ins = await c.env.DB.prepare(`
            INSERT INTO customer_assignments (customer_id, employee_id, assigned_by, notes)
            VALUES (?, ?, ?, ?)
          `).bind(customer_id, employeeId, assignedBy, noteAr).run()

          if (ins.meta.changes > 0) {
            await c.env.DB.prepare(`
              INSERT INTO assignment_history (customer_id, old_employee_id, new_employee_id, changed_by, notes)
              VALUES (?, NULL, ?, ?, ?)
            `).bind(customer_id, employeeId, assignedBy, noteAr).run()

            await c.env.DB.prepare(`
              INSERT INTO tenant_customer_auto_assign_state (tenant_id, last_auto_assigned_user_id, updated_at)
              VALUES (?, ?, CURRENT_TIMESTAMP)
              ON CONFLICT(tenant_id) DO UPDATE SET
                last_auto_assigned_user_id = excluded.last_auto_assigned_user_id,
                updated_at = CURRENT_TIMESTAMP
            `).bind(tenant_id, employeeId).run()
          }
        }
      }
    }
    
    return c.json({ 
      success: true, 
      customer_id: customer_id,
      tenant_id: tenant_id,
      message: 'تم حفظ بيانات العميل بنجاح'
    })
  } catch (error: any) {
    console.error('Save customer error:', error)
    return c.json({ 
      success: false, 
      error: error.message 
    }, 500)
  }
})

app.post('/api/calculator/submit-request', async (c) => {
  try {
    const data = await c.req.json()
    
    // Get tenant_id (from slug or default to first active tenant)
    const tenantSlug = data.tenant_slug || null
    let tenant_id = null
    
    if (tenantSlug) {
      const tenant = await c.env.DB.prepare(`
        SELECT id FROM tenants WHERE slug = ? AND status = 'active'
      `).bind(tenantSlug).first()
      
      if (tenant) {
        tenant_id = tenant.id
      }
    }
    
    // If no tenant_id from slug, get default tenant (first active tenant)
    if (!tenant_id) {
      const defaultTenant = await c.env.DB.prepare(`
        SELECT id FROM tenants WHERE status = 'active' ORDER BY id LIMIT 1
      `).first()
      
      if (defaultTenant) {
        tenant_id = defaultTenant.id
      }
    }
    
    // Step 1: Check if customer exists (by national_id or phone)
    let customer = await c.env.DB.prepare(`
      SELECT id, tenant_id FROM customers WHERE national_id = ? OR phone = ?
    `).bind(data.national_id, data.phone).first()
    
    let customer_id
    
    if (customer) {
      // Customer exists, use existing ID
      customer_id = customer.id
      
      // Update customer info (including all new fields)
      // Only update tenant_id if customer doesn't have one
      await c.env.DB.prepare(`
        UPDATE customers 
        SET full_name = ?, phone = ?, email = ?, 
            birthdate = ?, monthly_salary = ?,
            employer_name = ?, job_title = ?,
            work_start_date = ?, city = ?,
            tenant_id = COALESCE(tenant_id, ?),
            enrollment_source = COALESCE(enrollment_source, 'calculator')
        WHERE id = ?
      `).bind(
        data.full_name,
        data.phone,
        data.email || null,
        data.birthdate,
        data.monthly_salary,
        data.employer,
        data.job_title,
        data.work_start_date,
        data.city,
        tenant_id,
        customer_id
      ).run()
      
      // Use customer's tenant_id if available
      if (customer.tenant_id) {
        tenant_id = customer.tenant_id
      }
    } else {
      // Create new customer - but check one more time to avoid race condition
      try {
        const customerResult = await c.env.DB.prepare(`
          INSERT INTO customers (
            full_name, phone, email, national_id, 
            birthdate, monthly_salary, employer_name, 
            job_title, work_start_date, city, tenant_id,
            enrollment_source
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          data.full_name,
          data.phone,
          data.email || null,
          data.national_id,
          data.birthdate,
          data.monthly_salary,
          data.employer,
          data.job_title,
          data.work_start_date,
          data.city,
          tenant_id,
          'calculator'
        ).run()
        
        customer_id = customerResult.meta.last_row_id
      } catch (insertError: any) {
        // If UNIQUE constraint fails, customer was created between check and insert
        // Try to get the customer again
        if (insertError.message && insertError.message.includes('UNIQUE')) {
          const existingCustomer = await c.env.DB.prepare(`
            SELECT id, tenant_id FROM customers WHERE national_id = ? OR phone = ?
          `).bind(data.national_id, data.phone).first()
          
          if (existingCustomer) {
            customer_id = existingCustomer.id
            if (existingCustomer.tenant_id) {
              tenant_id = existingCustomer.tenant_id
            }
          } else {
            throw insertError
          }
        } else {
          throw insertError
        }
      }
    }
    
    // Step 2: Create financing request
    const requestResult = await c.env.DB.prepare(`
      INSERT INTO financing_requests (
        customer_id, financing_type_id, selected_bank_id,
        requested_amount, salary_at_request, duration_months,
        monthly_obligations, monthly_payment,
        status, notes
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?)
    `).bind(
      customer_id,
      data.financing_type_id,
      data.bank_id,
      data.requested_amount,
      data.monthly_salary,
      data.duration,
      data.monthly_obligations,
      data.monthly_payment,
      data.notes
    ).run()
    
    const requestId = requestResult.meta.last_row_id
    
    // Step 3: Create notification for new request
    await c.env.DB.prepare(`
      INSERT INTO notifications (user_id, title, message, type, category, related_request_id)
      VALUES (?, ?, ?, ?, ?, ?)
    `).bind(
      1, // Admin user
      'طلب تمويل جديد',
      `تم استلام طلب تمويل جديد برقم #${requestId} بمبلغ ${data.requested_amount.toLocaleString('ar-SA')} ريال من ${data.full_name}`,
      'info',
      'request',
      requestId
    ).run()
    
    return c.json({ 
      success: true, 
      request_id: requestId,
      customer_id: customer_id,
      message: 'تم إرسال طلبك بنجاح'
    })
  } catch (error: any) {
    console.error('Calculator submit error:', error)
    return c.json({ 
      success: false, 
      error: error.message,
      message: 'حدث خطأ أثناء إرسال الطلب. الرجاء المحاولة مرة أخرى.'
    }, 500)
  }
})

// Update request status
// Update financing request (full data)
app.put('/api/financing-requests/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const normRid = normalizeRoleId(userInfo.roleId)
    if (normRid === 3) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    const authHeader = c.req.header('Authorization')
    let tenantId = null
    
    // Extract tenant_id from JWT token
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const token = authHeader.substring(7)
      const parts = token.split('.')
      if (parts.length === 3) {
        const payload = JSON.parse(atob(parts[1]))
        tenantId = payload.tenant_id || null
      }
    }

    if (normRid === 5) {
      const scopeRow = await c.env.DB.prepare(`
        SELECT fr.id, fr.customer_id, fr.assigned_bank_agent_id, fr.created_by, fr.tenant_id, c.tenant_id AS customer_tenant_id
        FROM financing_requests fr
        LEFT JOIN customers c ON fr.customer_id = c.id
        WHERE fr.id = ?
      `)
        .bind(id)
        .first() as {
          id?: number
          customer_id?: number | null
          assigned_bank_agent_id?: number | null
          created_by?: number | null
          tenant_id?: number | null
          customer_tenant_id?: number | null
        } | null
      if (!scopeRow?.id) {
        return c.json({ success: false, error: 'Forbidden' }, 403)
      }
      const tid = userInfo.tenantId
      if (!tid) {
        return c.json({ success: false, error: 'Forbidden' }, 403)
      }
      const rowTenant = scopeRow.tenant_id != null ? Number(scopeRow.tenant_id) : Number(scopeRow.customer_tenant_id)
      if (Number(tid) !== rowTenant) {
        return c.json({ success: false, error: 'Forbidden' }, 403)
      }
      if (
        !(await canRole5AccessFinancingRequest(c.env.DB, userInfo, {
          customer_id: scopeRow.customer_id != null ? Number(scopeRow.customer_id) : null,
          customer_tenant_id: scopeRow.customer_tenant_id != null ? Number(scopeRow.customer_tenant_id) : null,
          assigned_bank_agent_id: scopeRow.assigned_bank_agent_id,
          created_by: scopeRow.created_by,
        }))
      ) {
        return c.json({ success: false, error: 'Forbidden' }, 403)
      }
    }
    
    const body = await c.req.json() as Record<string, unknown>
    const {
      requested_amount,
      duration_months,
      salary_at_request,
      monthly_obligations,
      identity_attachment_url,
      signature_attachment_url,
      salary_profile_attachment_url,
      gosi_attachment_url,
      tax_exemption_attachment_url,
      additional_1_attachment_url,
      additional_2_attachment_url,
      additional_3_attachment_url
    } = body as Record<string, any>

    const parseOptionalIntField = (raw: unknown): number | null | undefined => {
      if (raw === undefined) return undefined
      if (raw === null || raw === '') return null
      const n = parseInt(String(raw), 10)
      return Number.isNaN(n) ? null : n
    }

    const financing_type_id = parseOptionalIntField(body.financing_type_id)
    const selected_bank_id = parseOptionalIntField(body.selected_bank_id)
    const assigned_bank_agent_id = parseOptionalIntField(body.assigned_bank_agent_id)
    const statusRaw = body.status
    const notesRaw = body.notes

    // Determine the row's effective tenant for downstream validation lookups
    const rowMeta = await c.env.DB.prepare(
      `SELECT fr.tenant_id, fr.customer_id, c.tenant_id AS customer_tenant_id
       FROM financing_requests fr
       LEFT JOIN customers c ON fr.customer_id = c.id
       WHERE fr.id = ?`
    ).bind(id).first() as { tenant_id?: number | null; customer_id?: number | null; customer_tenant_id?: number | null } | null
    const effectiveTenantId =
      rowMeta?.tenant_id != null
        ? Number(rowMeta.tenant_id)
        : rowMeta?.customer_tenant_id != null
          ? Number(rowMeta.customer_tenant_id)
          : null

    // Validate the bank belongs to this tenant (when one is provided)
    if (selected_bank_id != null && effectiveTenantId != null) {
      const bankOk = await validateAssignedBankBelongsToTenant(c.env.DB, effectiveTenantId, selected_bank_id)
      if (!bankOk) {
        return c.json({ success: false, error: 'البنك غير صالح لهذه الشركة' }, 400)
      }
    }

    // Validate the bank agent (role 5) belongs to this tenant and a bank is selected
    if (assigned_bank_agent_id != null) {
      if (selected_bank_id == null) {
        return c.json({ success: false, error: 'يجب اختيار البنك عند تعيين موظف التمويل' }, 400)
      }
      if (effectiveTenantId == null) {
        return c.json({ success: false, error: 'تعذر تحديد الشركة لتعيين موظف التمويل' }, 400)
      }
      const agentOk = await validateBankAgentForFinancingRequest(c.env.DB, effectiveTenantId, assigned_bank_agent_id)
      if (!agentOk) {
        return c.json({ success: false, error: 'موظف التمويل غير صالح لهذه الشركة' }, 400)
      }
    }

    // Build update query with tenant_id check
    let updateFields: string[] = [
      'requested_amount = ?',
      'duration_months = ?',
      'salary_at_request = ?',
      'monthly_obligations = ?'
    ]

    const params: any[] = [
      requested_amount,
      duration_months,
      salary_at_request || 0,
      monthly_obligations || 0
    ]

    // Optionally update editable fields when they are present in the body
    if (financing_type_id !== undefined) {
      updateFields.push('financing_type_id = ?')
      params.push(financing_type_id)
    }
    if (selected_bank_id !== undefined) {
      updateFields.push('selected_bank_id = ?')
      params.push(selected_bank_id)
    }
    if (assigned_bank_agent_id !== undefined) {
      updateFields.push('assigned_bank_agent_id = ?')
      params.push(assigned_bank_agent_id)
    }
    if (statusRaw !== undefined && statusRaw !== null) {
      const statusStr = String(statusRaw).trim()
      if (statusStr !== '') {
        updateFields.push('status = ?')
        params.push(statusStr)
      }
    }
    if (notesRaw !== undefined) {
      updateFields.push('notes = ?')
      params.push(notesRaw == null ? '' : String(notesRaw))
    }
    
    // Add attachment URLs if provided
    if (identity_attachment_url) { updateFields.push('identity_attachment_url = ?'); params.push(identity_attachment_url) }
    if (signature_attachment_url) { updateFields.push('signature_attachment_url = ?'); params.push(signature_attachment_url) }
    if (salary_profile_attachment_url) { updateFields.push('salary_profile_attachment_url = ?'); params.push(salary_profile_attachment_url) }
    if (gosi_attachment_url) { updateFields.push('gosi_attachment_url = ?'); params.push(gosi_attachment_url) }
    if (tax_exemption_attachment_url) { updateFields.push('tax_exemption_attachment_url = ?'); params.push(tax_exemption_attachment_url) }
    if (additional_1_attachment_url) { updateFields.push('additional_1_attachment_url = ?'); params.push(additional_1_attachment_url) }
    if (additional_2_attachment_url) { updateFields.push('additional_2_attachment_url = ?'); params.push(additional_2_attachment_url) }
    if (additional_3_attachment_url) { updateFields.push('additional_3_attachment_url = ?'); params.push(additional_3_attachment_url) }
    
    params.push(id)
    
    let updateQuery = `
      UPDATE financing_requests 
      SET ${updateFields.join(', ')}
      WHERE id = ?
    `
    
    // Add tenant_id filter if not SuperAdmin. Bank agents (5) already scoped above;
    // rows may use customer tenant only (fr.tenant_id NULL) — JWT tenant would block the update.
    if (tenantId !== null && normRid !== 5) {
      updateQuery += ' AND tenant_id = ?'
      params.push(tenantId)
    }
    
    await c.env.DB.prepare(updateQuery).bind(...params).run()

    // Keep customer and all related requests in sync with request edit screen.
    const customerIdRow = await c.env.DB.prepare(`
      SELECT customer_id FROM financing_requests WHERE id = ?
    `).bind(id).first() as { customer_id?: number | null } | null
    const customerId = customerIdRow?.customer_id
    await syncAttachmentsForCustomer(c.env.DB, customerId, {
      identity_attachment_url,
      signature_attachment_url,
      salary_profile_attachment_url,
      gosi_attachment_url,
      tax_exemption_attachment_url,
      additional_1_attachment_url,
      additional_2_attachment_url,
      additional_3_attachment_url
    })
    
    return c.json({ success: true })
  } catch (error: any) {
    console.error('Update financing request error:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Update financing request status only
app.put('/api/financing-requests/:id/status', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (normalizeRoleId(requester.roleId) === 5) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const id = c.req.param('id')
    const { status, notes } = await c.req.json()
    
    // Get old status
    const oldRequest = await c.env.DB.prepare(`
      SELECT status FROM financing_requests WHERE id = ?
    `).bind(id).first()
    
    // Update status and timestamp based on new status
    const timestampFields = {
      'pending': 'pending_at',
      'under_review': 'under_review_at',
      'processing': 'processing_at',
      'approved': 'approved_at',
      'rejected': 'rejected_at'
    }
    
    const timestampField = timestampFields[status as keyof typeof timestampFields]
    
    if (timestampField) {
      await c.env.DB.prepare(`
        UPDATE financing_requests 
        SET status = ?, notes = ?, ${timestampField} = datetime('now'), reviewed_at = datetime('now')
        WHERE id = ?
      `).bind(status, notes, id).run()
    } else {
      await c.env.DB.prepare(`
        UPDATE financing_requests SET status = ?, notes = ? WHERE id = ?
      `).bind(status, notes, id).run()
    }
    
    // Record status change in history
    if (oldRequest && oldRequest.status !== status) {
      await c.env.DB.prepare(`
        INSERT INTO financing_request_status_history (request_id, old_status, new_status, changed_by, notes)
        VALUES (?, ?, ?, 'admin', ?)
      `).bind(id, oldRequest.status, status, notes || '').run()
    }
    
    // Get request details
    const request = await c.env.DB.prepare(`
      SELECT requested_amount FROM financing_requests WHERE id = ?
    `).bind(id).first()
    
    // Create notification for status change
    const statusMessages = {
      'pending': 'قيد الانتظار',
      'under_review': 'قيد المراجعة',
      'approved': 'موافق عليه',
      'rejected': 'مرفوض'
    }
    
    const statusTypes = {
      'pending': 'info',
      'under_review': 'warning',
      'approved': 'success',
      'rejected': 'error'
    }
    
    await c.env.DB.prepare(`
      INSERT INTO notifications (user_id, title, message, type, category, related_request_id)
      VALUES (?, ?, ?, ?, ?, ?)
    `).bind(
      1, // Admin user
      'تحديث حالة الطلب',
      `تم تحديث حالة الطلب #${id} إلى: ${statusMessages[status as keyof typeof statusMessages] || status}`,
      statusTypes[status as keyof typeof statusTypes] || 'info',
      'status_change',
      id
    ).run()
    
    return c.json({ success: true })
  } catch (error: any) {
    console.error('Update status error:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// ATTACHMENTS APIs

// Upload attachment to R2
app.post('/api/attachments/upload', async (c) => {
  try {
    if (!c.env?.ATTACHMENTS) {
      return c.json({ success: false, error: 'Attachment storage not configured' }, 500)
    }

    const formData = await c.req.formData()
    const fileEntry = formData.get('file')
    const requestId = String(formData.get('request_id') || '').trim()
    const rawAttachmentType = String(formData.get('attachmentType') || formData.get('attachment_type') || '').trim()
    const allowedAttachmentTypes = new Set([
      'identity',
      'signature',
      'salary_profile',
      'gosi',
      'tax_exemption',
      'additional_1',
      'additional_2',
      'additional_3'
    ])
    const attachmentType = rawAttachmentType.toLowerCase()
    
    if (!allowedAttachmentTypes.has(attachmentType)) {
      return c.json({ success: false, error: 'Invalid attachment type' }, 400)
    }

    if (!fileEntry || !(fileEntry instanceof File)) {
      return c.json({ success: false, error: 'No file provided' }, 400)
    }

    const file = fileEntry
    const maxAttachmentSizeBytes = 2 * 1024 * 1024 // 2MB

    if (file.size > maxAttachmentSizeBytes) {
      return c.json({ success: false, error: 'File too large. Max size is 2MB' }, 400)
    }

    // Generate unique filename
    const timestamp = Date.now()
    const random = Math.random().toString(36).substring(7)
    const rawExtension = file.name.split('.').pop() || 'bin'
    const fileExtension = rawExtension.replace(/[^a-z0-9]/gi, '').toLowerCase() || 'bin'
    const filename = requestId 
      ? `${requestId}/${attachmentType}_${timestamp}.${fileExtension}`
      : `temp/${attachmentType}_${timestamp}_${random}.${fileExtension}`
    
    // Upload to R2
    const arrayBuffer = await file.arrayBuffer()
    await c.env.ATTACHMENTS.put(filename, arrayBuffer, {
      httpMetadata: {
        contentType: file.type
      }
    })
    
    const publicUrl = `/api/attachments/view/${filename}`
    
    // Update database only if requestId is provided
    if (requestId) {
      if (!c.env?.DB) {
        return c.json({ success: false, error: 'Database not configured' }, 500)
      }

      const attachmentColumns: Record<string, string> = {
        identity: 'identity_attachment_url',
        signature: 'signature_attachment_url',
        salary_profile: 'salary_profile_attachment_url',
        gosi: 'gosi_attachment_url',
        tax_exemption: 'tax_exemption_attachment_url',
        additional_1: 'additional_1_attachment_url',
        additional_2: 'additional_2_attachment_url',
        additional_3: 'additional_3_attachment_url'
      }
      const columnName = attachmentColumns[attachmentType]
      console.log('📎 Updating attachment:', { requestId, attachmentType, columnName, publicUrl })
      
      const result = await c.env.DB.prepare(`
        UPDATE financing_requests 
        SET ${columnName} = ? 
        WHERE id = ?
      `).bind(publicUrl, requestId).run()
      
      console.log('✅ Update result:', result)
      const requestRow = await c.env.DB.prepare(`
        SELECT customer_id FROM financing_requests WHERE id = ?
      `).bind(requestId).first() as { customer_id?: number | null } | null
      const attachmentSyncPayload: AttachmentSyncPayload = {}
      if (columnName === 'identity_attachment_url') attachmentSyncPayload.identity_attachment_url = publicUrl
      if (columnName === 'signature_attachment_url') attachmentSyncPayload.signature_attachment_url = publicUrl
      if (columnName === 'salary_profile_attachment_url') attachmentSyncPayload.salary_profile_attachment_url = publicUrl
      if (columnName === 'gosi_attachment_url') attachmentSyncPayload.gosi_attachment_url = publicUrl
      if (columnName === 'tax_exemption_attachment_url') attachmentSyncPayload.tax_exemption_attachment_url = publicUrl
      if (columnName === 'additional_1_attachment_url') attachmentSyncPayload.additional_1_attachment_url = publicUrl
      if (columnName === 'additional_2_attachment_url') attachmentSyncPayload.additional_2_attachment_url = publicUrl
      if (columnName === 'additional_3_attachment_url') attachmentSyncPayload.additional_3_attachment_url = publicUrl
      await syncAttachmentsForCustomer(c.env.DB, requestRow?.customer_id, {
        ...attachmentSyncPayload
      })
    }
    
    return c.json({ 
      success: true, 
      url: publicUrl,
      filename: filename
    })
  } catch (error: any) {
    console.error('Upload error:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// View/Download attachment from R2
app.get('/api/attachments/view/:path{.+}', async (c) => {
  try {
    if (!c.env?.ATTACHMENTS) {
      return c.json({ success: false, error: 'Attachment storage not configured' }, 500)
    }

    const path = c.req.param('path')
    const object = await c.env.ATTACHMENTS.get(path)
    
    if (!object) {
      return c.notFound()
    }
    
    const headers = new Headers()
    object.writeHttpMetadata(headers)
    headers.set('etag', object.httpEtag)
    
    return new Response(object.body, { headers })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Delete attachment from R2
app.delete('/api/attachments/delete/:path{.+}', async (c) => {
  try {
    if (!c.env?.ATTACHMENTS) {
      return c.json({ success: false, error: 'Attachment storage not configured' }, 500)
    }

    const path = c.req.param('path')
    
    // Delete from R2
    await c.env.ATTACHMENTS.delete(path)
    
    // Update database to remove the URL
    // Extract request_id and attachment type from path
    // Path format: {request_id}/{type}_{timestamp}.{ext}
    const pathParts = path.split('/')
    if (pathParts.length === 2) {
      const requestId = pathParts[0]
      const filename = pathParts[1]
      
      // Determine attachment type from filename
      let columnName = null
      if (filename.startsWith('identity_')) columnName = 'identity_attachment_url'
      else if (filename.startsWith('signature_')) columnName = 'signature_attachment_url'
      else if (filename.startsWith('salary_profile_')) columnName = 'salary_profile_attachment_url'
      else if (filename.startsWith('gosi_')) columnName = 'gosi_attachment_url'
      else if (filename.startsWith('tax_exemption_')) columnName = 'tax_exemption_attachment_url'
      else if (filename.startsWith('additional_1_')) columnName = 'additional_1_attachment_url'
      else if (filename.startsWith('additional_2_')) columnName = 'additional_2_attachment_url'
      else if (filename.startsWith('additional_3_')) columnName = 'additional_3_attachment_url'
      
      // Update database if we identified the column
      if (columnName) {
        await c.env.DB.prepare(`
          UPDATE financing_requests 
          SET ${columnName} = NULL 
          WHERE id = ?
        `).bind(requestId).run()
        try {
          await c.env.DB.prepare(`
            UPDATE customers
            SET ${columnName} = NULL
            WHERE id = (SELECT customer_id FROM financing_requests WHERE id = ?)
          `).bind(requestId).run()
        } catch (customerAttachmentError) {
          if (!isMissingCustomerAttachmentsColumnError(customerAttachmentError)) throw customerAttachmentError
        }
      }
    }
    
    return c.json({ success: true })
  } catch (error: any) {
    console.error('Delete error:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

