    await c.env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_payments_customer ON payments(customer_id)').run()
    await c.env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_payments_employee ON payments(employee_id)').run()
